-- Stores the actual PDF generated by the browser (html2canvas + jsPDF,
-- same approach as the Experience Letter tool). This replaces relying on
-- PdfGenerationService to rebuild the PDF server-side from structured
-- fields only — that approach couldn't reflect any inline edits made to
-- the rendered letter, since the server never saw that edited text.
--
-- pdf_data is nullable so older rows saved before this migration (which
-- only ever have server-generated PDFs) keep working: the backend falls
-- back to PdfGenerationService when pdf_data is null.

alter table appraisals add column if not exists pdf_data bytea;
